import React from "react";
import { gql, useQuery, useMutation } from "@apollo/client";

// ============================================================
// HELPER
// ============================================================
function formatDuration(seconds) {
  if (!seconds && seconds !== 0) return "—";
  const m = Math.floor(seconds / 60);
  const s = String(seconds % 60).padStart(2, "0");
  return `${m}:${s}`;
}

// ============================================================
// QUERIES & MUTATIONS
// ============================================================
const LIKED_TRACKS = gql`
  query likedTracks {
    likedTracks {
      id
      createdAt
      track {
        id
        title
        duration
        rank
        explicit_lyrics
        artist { name }
        album { title cover_medium }
      }
    }
  }
`;

const UNLIKE_TRACK = gql`
  mutation UnlikeTrack($trackId: ID!) {
    unlikeTrack(trackId: $trackId) {
      acknowledged
    }
  }
`;

// ============================================================
// COMPOSANT
// ============================================================
export default function LikedTracks({ token }) {

  const authHeaders = {
    context: {
      headers: {
        authorization: `Bearer ${token}`,
      },
    },
  };

  const { data, loading, error, refetch } = useQuery(LIKED_TRACKS, {
    ...authHeaders,
  });

  const [unlikeTrack] = useMutation(UNLIKE_TRACK, {
    ...authHeaders,
    onCompleted: () => refetch(),
  });

  // ============================================================
  // STATES
  // ============================================================
  if (!token) return <div className="empty">🔐 Connecte-toi</div>;
  if (loading) return <div className="loading">⏳ Chargement...</div>;
  if (error) return <div className="error">❌ {error.message}</div>;

  const likedTracks = data?.likedTracks || [];

  // ============================================================
  // VIEW
  // ============================================================
  return (
    <div>
      <h2>❤️ Mes titres likés</h2>

      <div className="items-grid">
        {likedTracks.map((l) => {
          const t = l.track;

          return (
